/* Auth gate — schedule-safe (headers only on manual path). */
const req = $input.first().json;
const headers = req.headers || {};
if (headers && Object.keys(headers).length > 0) {
  const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
  if (provided !== $env.CHAT_API_KEY) { return [{ json: { __error: true, status: 401, body: { ok: false, error: 'Invalid API key' } } }]; }
}
return [{ json: { ok: true } }];

/* Extract action items from meeting notes via LLM, then create todos. */
const req = $('Webhook Meeting').first().json;
const body = req.body || {};
const text = String(body.text || '').trim().slice(0, 6000);
if (text.length < 5) return [{ json: { ok: false, error: 'text required (meeting notes)' } }];
const sys = '你是会议行动项提取器。从给定的会议记录中提取可执行的行动项（谁/做什么/何时）。只提取真正需要执行的事项，最多 8 条；忽略讨论背景与已完成事项。输出严格 JSON：{"items":[{"text":"...","owner":"...或空","due":"YYYY-MM-DD 或空"}]}，没有则 {"items":[]}。只输出 JSON。';
let items = [];
try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.deepseek.com/chat/completions', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.UPSTREAM_API_KEY || ''), 'Content-Type': 'application/json' }, body: { model: 'deepseek-v4-flash', messages: [{ role: 'system', content: sys }, { role: 'user', content: text }], stream: false, temperature: 0.2, max_tokens: 2400 }, timeout: 90000 });
  const raw = String((r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '');
  const i = raw.indexOf('{'); const j = raw.lastIndexOf('}');
  const parsed = JSON.parse(raw.slice(i, j + 1));
  items = Array.isArray(parsed.items) ? parsed.items.slice(0, 8) : [];
} catch (e) { return [{ json: { ok: false, error: 'extract failed: ' + String(e.message || e).slice(0, 150) } }]; }
const added = [];
for (const it of items) {
  const t = String((it && it.text) || '').trim().slice(0, 200);
  if (t.length < 2) continue;
  const owner = String((it && it.owner) || '').trim().slice(0, 30);
  const due = /^\d{4}-\d{2}-\d{2}$/.test(String((it && it.due) || '')) ? String(it.due) : undefined;
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/admin/todos/add', headers: { Authorization: ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || ''), 'Content-Type': 'application/json' }, body: { text: (owner ? '【' + owner + '】' : '') + t, due_date: due, via: 'meeting-actions' }, timeout: 15000 });
    if (!(r && r.ok === false)) added.push({ text: t, owner: owner || null, due: due || null, id: (r && (r.id || (r.todo && r.todo.id))) || null });
  } catch (e2) {}
}
return [{ json: { ok: true, found: items.length, added: added.length, items: added } }];
